L44_1 = "\227\129\145\227\129\169\227\128\129\227\129\161\227\130\135\227\129\134\227\129\169\227\129\157\227\130\140\227\129\143\227\130\137\227\129\132\227\129\174\227\130\168\227\130\191\227\131\139\227\130\166\227\131\160\227\130\146\230\143\144\228\190\155\227\129\151\227\129\166\227\129\143\227\130\140\227\130\139\229\165\180\227\130\137\227\129\174\232\169\177\227\130\146\232\129\158\227\129\141\227\129\164\227\129\145\227\129\159\227\130\147\227\129\160\227\128\130"
L43_1.m_Talk_JPN = L44_1
