L44_1 = "\228\184\141\233\129\142\239\188\140\230\156\128\232\191\145\230\136\145\232\129\189\232\170\170\230\156\137\228\186\155\230\156\139\229\143\139\230\173\163\229\165\189\232\131\189\230\143\144\228\190\155\233\128\153\233\186\188\229\164\154\231\154\132\230\176\184\230\129\134\228\185\139\233\135\145\227\128\130"
