L44_1 = "\224\185\129\224\184\149\224\185\136\224\184\156\224\184\161\224\185\132\224\184\148\224\185\137\224\184\162\224\184\180\224\184\153\224\184\167\224\185\136\224\184\178\224\184\161\224\184\181\224\184\129\224\184\165\224\184\184\224\185\136\224\184\161\224\184\132\224\184\153\224\184\151\224\184\181\224\185\136\224\184\170\224\184\178\224\184\161\224\184\178\224\184\163\224\184\150\224\184\171\224\184\178\224\184\173\224\184\181\224\185\128\224\184\151\224\184\173\224\184\163\224\185\140\224\185\128\224\184\153\224\184\181\224\184\162\224\184\161\224\184\136\224\184\179\224\184\153\224\184\167\224\184\153\224\184\130\224\184\153\224\184\178\224\184\148\224\184\153\224\184\181\224\185\137\224\185\132\224\184\148\224\185\137"
